insert into ns_festivals (id, dev, newa, roman, en, aliases, anchor, span_days, tradition, places, summary, is_new_year, public_holiday, declared_annually, status, sources) values ('ghyah-chaku-sanhu', 'घ्यः चाकु सँल्हु', '𑐑𑑂𑐫𑑅 𑐔𑐵𑐎𑐸 𑐳𑑃𑐯𑐸', 'Ghyah Chāku Sanhu', 'Māghe Sankrānti', array['maghe sankranti','ghyo chaku']::text[], '{"kind":"sankranti","rashi":9}'::jsonb, 1, 'hindu', array['Nepal-wide']::text[], 'घ्यू, चाकु, तिलको लड्डु र तरुल खाने दिन।', false, 'national', false, 'review', array['wiki_sila']::text[]) on conflict (id) do update set dev = excluded.dev, anchor = excluded.anchor, updated_at = now();
insert into ns_festivals (id, dev, newa, roman, en, aliases, anchor, span_days, tradition, places, summary, is_new_year, public_holiday, declared_annually, status, sources) values ('biska', 'बिस्का जात्रा', '𑐧𑐶𑐳𑑂𑐎𑐵 𑐖𑐵𑐟𑑂𑐬𑐵', 'Biskā Jātrā', 'Bisket Jātrā (Bhaktapur, Thimi)', array['bisket jatra','biska','sindur jatra']::text[], '{"kind":"sankranti","rashi":0,"offsetDays":-4}'::jsonb, 9, 'hindu', array['Bhaktapur','Thimi','Bode']::text[], 'भैरव–भद्रकालीको रथ तान्ने, योसिं (लिंगो) ठड्याउने र ढाल्ने; मेष संक्रान्तिमा केन्द्रित।', false, 'none', true, 'review', array[]::text[]) on conflict (id) do update set dev = excluded.dev, anchor = excluded.anchor, updated_at = now();
